def ensure_future(days=7):
    for d in range(0, days+1):
        day = today() + d
        name = f'events_{day:%Y_%m_%d}'
        if not exists(name):
            exec(f"CREATE TABLE {name} PARTITION OF events FOR VALUES FROM ('{day}') TO ('{day+1}') PARTITION BY HASH (entity_id)")
            for r in range(16):
                exec(f'CREATE TABLE {name}_p{r} PARTITION OF {name} FOR VALUES WITH (MODULUS 16, REMAINDER {r})')
    if count_future() < 3: alert('partition pre-creation lagging')

def route(ev):
    if ev.event_ts < now() - 7d:
        return 'events_late'
    if ev.event_ts > now() + 1h:
        return 'reject_clock_skew'
    return 'events'
